(function(){
function withKiosk(url){if(!url){return url;}return /[?&]kiosk(?:[=&]|$)/.test(url)?url:url+(url.indexOf('?')>=0?'&':'?')+'kiosk';}function fallbackUrl(query){return withKiosk('/dashboards?query='+encodeURIComponent(query||''));}
function goByQuery(query,title){
  var fallback=fallbackUrl(query||title);
  if(!query&&!title){window.location.assign('/dashboards?kiosk');return;}
  fetch('/api/search?type=dash-db&query='+encodeURIComponent(query||title),{credentials:'same-origin'})
    .then(function(r){return r.ok?r.json():[];})
    .then(function(items){
      var exact=title?(items||[]).find(function(item){return item.title===title;}):null;
      var found=exact||(items||[])[0];
      window.location.assign(found&&found.url?withKiosk(found.url):fallback);
    })
    .catch(function(){window.location.assign(fallback);});
}
