})();

(function(){
function escapeHtml(v){return String(v==null?'':v).replace(/[&<>]/g,function(c){return c==='&'?'&amp;':(c==='<'?'&lt;':'&gt;');});}
function normalizeSearchText(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');}
function valuesToArray(values){if(!values)return[];if(Array.isArray(values))return values;if(typeof values.toArray==='function')return values.toArray();var len=values.length||values.size||(values.buffer?values.buffer.length:0)||0;var out=[];for(var i=0;i<len;i++){out.push(typeof values.get==='function'?values.get(i):values[i]);}return out;}
function toMs(v){if(v instanceof Date)return v.getTime();if(typeof v==='number')return v;var p=new Date(v).getTime();return Number.isFinite(p)?p:0;}
function fieldByName(frame,name){var fields=(frame&&frame.fields)||[];var lower=name.toLowerCase();for(var i=0;i<fields.length;i++){var f=fields[i];var n1=String(f.name||'').toLowerCase();var n2=String((f.config&&f.config.displayName)||'').toLowerCase();if(n1===lower||n2===lower)return f;}return null;}
var TABLE_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='4' width='18' height='16' rx='2'/><path d='M3 10h18'/><path d='M9 4v16'/></svg>";
var SEARCH_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.3' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='7'/><path d='m20 20-3.5-3.5'/></svg>";
var CSV_ICON="<svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.1' stroke-linecap='round' stroke-linejoin='round'><path d='M14 2H7a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7Z'/><path d='M14 2v5h5'/><path d='M8 16h8'/><path d='M8 12h8'/></svg>";
var SEV_ORDER=['error','warn','info','debug','trace'];
var SEV_META={error:{label:'Error',cls:'sev-error'},warn:{label:'Warn',cls:'sev-warn'},info:{label:'Info',cls:'sev-info'},debug:{label:'Debug',cls:'sev-debug'},trace:{label:'Trace',cls:'sev-trace'}};
var rows=[];
var frame=data&&data.series&&data.series[0];
if(frame){
var timeField=fieldByName(frame,'Hora')||fieldByName(frame,'Time');
var origemField=fieldByName(frame,'Origem');
var sevField=fieldByName(frame,'Nivel');
var traceField=fieldByName(frame,'TraceId');
var msgField=fieldByName(frame,'Mensagem');
var times=timeField?valuesToArray(timeField.values):[];
var origens=origemField?valuesToArray(origemField.values):[];
var sevs=sevField?valuesToArray(sevField.values):[];
var traces=traceField?valuesToArray(traceField.values):[];
var msgs=msgField?valuesToArray(msgField.values):[];
var n=times.length;
for(var i=0;i<n;i++){
var sevRaw=String(sevs[i]||'').toLowerCase();
rows.push({time:toMs(times[i]),origem:String(origens[i]||'N/A'),severity:SEV_META[sevRaw]?sevRaw:'info',traceId:String(traces[i]||'-'),mensagem:String(msgs[i]||'-')});
}
}
window.__logPanelStateSpring=window.__logPanelStateSpring||{activeSeverity:'all',searchTerm:'',currentPage:1};
var state=window.__logPanelStateSpring;
var itemsPerPage=15;
var debounceTimer=null;
var rightContainer=htmlNode.querySelector('#log-problems-container');
function formatAge(ms){if(!ms)return '-';var diff=Math.floor((Date.now()-ms)/1000);if(diff<60)return Math.max(0,diff)+'s atras';if(diff<3600)return Math.floor(diff/60)+'m atras';if(diff<86400)return Math.floor(diff/3600)+'h atras';return Math.floor(diff/86400)+'d atras';}
function formatHora(ms){if(!ms)return '-';var d=new Date(ms);return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('pt-BR');}
function exportCsv(list){var Q=String.fromCharCode(34);var esc=function(v){v=String(v==null?'':v).split(Q).join(Q+Q);return Q+v+Q;};var header=[esc('Origem'),esc('Nivel'),esc('TraceId'),esc('Mensagem'),esc('Hora')].join(';');var lines=[header];list.forEach(function(r){lines.push([esc(r.origem),esc(r.severity),esc(r.traceId),esc(r.mensagem),esc(formatHora(r.time))].join(';'));});var csv=String.fromCharCode(65279)+lines.join(String.fromCharCode(13,10));var blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='logs-'+Date.now()+'.csv';document.body.appendChild(a);a.click();document.body.removeChild(a);setTimeout(function(){URL.revokeObjectURL(url);},1000);}
function renderRightPanel(){
if(!rightContainer)return;
var filtered=rows.filter(function(r){
if(state.activeSeverity!=='all'&&r.severity!==state.activeSeverity)return false;
if(state.searchTerm){var s=normalizeSearchText(state.searchTerm);var hay=normalizeSearchText(r.origem+' '+r.traceId+' '+r.mensagem);if(hay.indexOf(s)===-1)return false;}
return true;
});
filtered.sort(function(a,b){return b.time-a.time;});
var totalPages=Math.max(1,Math.ceil(filtered.length/itemsPerPage));
if(state.currentPage>totalPages)state.currentPage=totalPages;
if(state.currentPage<1)state.currentPage=1;
var start=(state.currentPage-1)*itemsPerPage;
var pageItems=filtered.slice(start,start+itemsPerPage);
var rowsHtml='';
pageItems.forEach(function(r){
var meta=SEV_META[r.severity];
var rowClass=r.severity==='error'?'row-error':(r.severity==='warn'?'row-warn':'');
rowsHtml+="<tr class='"+rowClass+"'><td class='cell-host'>"+escapeHtml(r.origem)+"</td><td><span class='severity-badge "+meta.cls+"'>"+escapeHtml(r.severity)+"</span></td><td class='cell-trace' title='"+escapeHtml(r.traceId)+"'>"+escapeHtml(r.traceId)+"</td><td class='cell-problem'><div class='cell-problem-wrap'><span class='cell-problem-text'>"+escapeHtml(r.mensagem)+"</span><button class='copy-log-btn' type='button' title='Copiar mensagem' data-copy='"+escapeHtml(r.mensagem)+"'>"+CSV_ICON+"</button></div></td><td>"+formatAge(r.time)+"</td><td>"+formatHora(r.time)+"</td></tr>";
});
if(!rowsHtml){
rowsHtml="<tr class='problems-empty-row'><td colspan='6'>Nenhum log encontrado para os filtros selecionados.</td></tr>";
}
var filterButtonsHtml="<button class='filter-btn filter-btn-severity "+(state.activeSeverity==='all'?'active':'')+"' data-sev='all' type='button'>All</button>";
filterButtonsHtml+=SEV_ORDER.map(function(sv){
var meta=SEV_META[sv];
return "<button class='filter-btn filter-btn-severity btn-"+sv+" "+(state.activeSeverity===sv?'active':'')+"' data-sev='"+sv+"' type='button'>"+meta.label+"</button>";
}).join('');
rightContainer.innerHTML =
"<div class='log-section-header'><div class='log-section-header-left'><span class='log-section-icon'><span class='svg-icon' aria-hidden='true'>"+TABLE_ICON+"</span></span><div><div class='log-section-title'>Logs da Aplicação</div><div class='log-section-sub'>Busca detalhada por nível e conteúdo</div></div></div></div>"+
"<div class='problems-table-panel'>"+
"<div class='filter-bar'>"+
"<div class='filter-group'><span class='filter-label'>Nível:</span>"+filterButtonsHtml+"</div>"+
"<div class='search-bar-group'>"+
"<div class='search-input-wrapper'><span class='svg-icon' aria-hidden='true'>"+SEARCH_ICON+"</span>"+
"<input type='text' id='problem-search-input' class='search-input' placeholder='Buscar origem, traceId ou mensagem...' value='"+escapeHtml(state.searchTerm)+"'/></div>"+
"<button class='pagination-btn export-btn' id='btn-export' type='button' title='Exportar CSV'><span class='svg-icon' aria-hidden='true'>"+CSV_ICON+"</span></button>"+
"</div></div>"+
"<div class='table-wrapper'><table class='problems-table'><thead><tr><th>Origem</th><th>Nível</th><th>TraceId</th><th>Mensagem</th><th>Idade</th><th>Hora</th></tr></thead><tbody>"+rowsHtml+"</tbody></table></div>"+
"<div class='pagination-controls'><span class='pagination-info'>Pagina "+state.currentPage+" de "+totalPages+" &middot; "+filtered.length+" log(s)</span>"+
"<div class='pagination-buttons'>"+
"<button class='pagination-btn' id='btn-prev' type='button' "+(state.currentPage===1?'disabled':'')+">Anterior</button>"+
"<button class='pagination-btn' id='btn-next' type='button' "+(state.currentPage===totalPages?'disabled':'')+">Proxima</button>"+
"</div></div></div>";
var searchInput=rightContainer.querySelector('#problem-search-input');
if(searchInput){
searchInput.oninput=function(ev){
var value=ev.target.value;
clearTimeout(debounceTimer);
debounceTimer=setTimeout(function(){
state.searchTerm=value;
state.currentPage=1;
renderRightPanel();
var updated=rightContainer.querySelector('#problem-search-input');
if(updated){updated.focus();updated.setSelectionRange(value.length,value.length);}
},400);
};
}
var sevButtons=rightContainer.querySelectorAll('.filter-btn-severity');
for(var i=0;i<sevButtons.length;i++){
(function(btn){
btn.onclick=function(){
state.activeSeverity=btn.getAttribute('data-sev')||'all';
state.currentPage=1;
renderRightPanel();
};
})(sevButtons[i]);
}
var prevBtn=rightContainer.querySelector('#btn-prev');
if(prevBtn){prevBtn.onclick=function(){if(state.currentPage>1){state.currentPage-=1;renderRightPanel();}};}
