for(var ci=0;ci<copyButtons.length;ci++){
(function(btn){btn.onclick=function(){var text=btn.getAttribute('data-copy')||'';if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text);}btn.classList.add('copied');setTimeout(function(){btn.classList.remove('copied');},900);};})(copyButtons[ci]);
